// dateUtils.ts
export function getCardExpiryDate(monthStr: string, yearStr: string): Date {
  const month = parseInt(monthStr);
  const year = parseInt(yearStr);
  const currentYear = new Date().getFullYear();

  // Determine century based on current year
  const twoDigitYear = currentYear % 100;
  const century = currentYear - twoDigitYear;
  const fullYear = year > twoDigitYear + 50 ? century - 100 + year : century + year;

  // Last day of expiry month
  return new Date(fullYear, month, 0); // day 0 = last day of previous month
}

export function addSubscriptionDuration(baseDate: Date, durationDays: number): Date {
  const date = new Date(baseDate);
  date.setDate(date.getDate() + durationDays);
  return date;
}

